import{_ as i,C as n,o as e,c as l,a2 as r,b as a,w as d,a as E,E as c,a3 as s}from"./chunks/framework.CFuv5BrO.js";const _=JSON.parse('{"title":"Hearth 前端架构设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-前端架构设计说明.md","filePath":"architecture/Hearth-前端架构设计说明.md","lastUpdated":null}'),h={name:"architecture/Hearth-前端架构设计说明.md"};function A(B,t,p,b,g,u){const o=n("Mermaid");return e(),l("div",null,[t[4]||(t[4]=r('<h1 id="hearth-前端架构设计说明" tabindex="-1">Hearth 前端架构设计说明 <a class="header-anchor" href="#hearth-前端架构设计说明" aria-label="Permalink to &quot;Hearth 前端架构设计说明&quot;">​</a></h1><blockquote><p><strong>阅读范围</strong>：本文只依据项目源码整理（<code>apps/web/src</code>、<code>apps/web/public</code>、Vite / TS 配置，以及 <code>apps/server</code> 中托管静态资源的代码），未参考 <code>docs/</code> 与 <code>README.md</code>。 <strong>表达方式</strong>：只讲设计思路与运行机制，不粘贴任何项目源码；文中括号内的文件名仅用于定位核对；示意图为结构性图示，不是代码。 <strong>整理日期</strong>：2026-11-13</p></blockquote><hr><h2 id="_0-一句话看懂" tabindex="-1">0. 一句话看懂 <a class="header-anchor" href="#_0-一句话看懂" aria-label="Permalink to &quot;0. 一句话看懂&quot;">​</a></h2><p>这个前端不是一套「业务表单系统」，而是一台<strong>本地 Agent 的运行控制台</strong>：界面围绕「聊天派活 → 任务执行 → 需要人确认 → 结果审计」组织，状态上采用 <strong>「缓存即状态、事件只报脏」</strong> 的模型。</p><p>整个项目只有一个前端应用 <code>apps/web</code>，是 React + TypeScript + Vite 的单页应用。它不引入 UI 组件库，也不引入 Redux / Zustand 之类的状态库，而是把 TanStack Query 的缓存当成唯一的服务端状态仓库。</p>',6)),(e(),a(s,null,{default:d(()=>[c(o,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E8%81%8A%E5%A4%A9%E5%8F%91%E8%B5%B7%3Cbr%2F%3E%E9%97%AE%E7%AD%94%E6%88%96%E6%B4%BE%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20B%5B%22%E4%BB%BB%E5%8A%A1%E6%89%A7%E8%A1%8C%3Cbr%2F%3E%E6%89%A7%E8%A1%8C%E5%99%A8%20%2F%20%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E9%9C%80%E8%A6%81%E4%BD%A0%3Cbr%2F%3E%E5%AE%A1%E6%89%B9%20%C2%B7%20%E8%A1%A5%E5%85%85%20%C2%B7%20%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E7%BB%93%E6%9E%9C%E5%AE%A1%E8%AE%A1%3Cbr%2F%3E%E4%BA%A7%E7%89%A9%20%C2%B7%20Git%20%C2%B7%20%E4%BA%8B%E4%BB%B6%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20%20%20D%20-.-%3E%7C%22%E8%A1%A5%E5%85%85%E6%8C%87%E4%BB%A4%E5%9B%9E%E6%B5%81%22%7C%20A%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=r('<hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为有复杂的前端状态管理</td><td><strong>没有全局状态库</strong>。服务端状态全在 Query 缓存里，瞬时交互状态是组件本地 <code>useState</code>，跨页偏好才用 Context 或 localStorage</td></tr><tr><td>以为 SSE 推送业务数据</td><td>全局事件流<strong>只当「缓存脏了」的信号</strong>，真正的数据仍由 REST 重新拉取；只有聊天流是例外，直接把内容吐给页面</td></tr><tr><td>以为是个多页面网站</td><td>只有一个 SPA、一个 HTML 外壳；服务端把非 <code>/api</code> 的 GET 全部回退到 <code>index.html</code>，深链接靠前端路由解析</td></tr></tbody></table><hr><h2 id="_2-技术选型与工程位置" tabindex="-1">2. 技术选型与工程位置 <a class="header-anchor" href="#_2-技术选型与工程位置" aria-label="Permalink to &quot;2. 技术选型与工程位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>选择</th><th>说明</th></tr></thead><tbody><tr><td>框架</td><td>React 18 + TypeScript</td><td><code>jsx: react-jsx</code>，<code>noEmit</code>，由 Vite 负责转译</td></tr><tr><td>构建</td><td>Vite 7</td><td>开发端口 <code>127.0.0.1:5173</code>，<code>/api</code> 代理到 <code>127.0.0.1:4317</code>；构建输出 <code>dist</code> 并带 sourcemap</td></tr><tr><td>路由</td><td>react-router-dom v7</td><td>BrowserRouter，嵌套布局 + <code>Outlet</code></td></tr><tr><td>服务端状态</td><td>TanStack Query v5</td><td>全局默认：5 秒新鲜期、失败重试 1 次、窗口聚焦自动重取</td></tr><tr><td>其余依赖</td><td>lucide-react / react-markdown / remark-gfm</td><td>图标、Markdown 消息渲染（支持表格等 GFM 语法）</td></tr><tr><td>样式</td><td>纯手写 CSS</td><td>无预处理器、无 CSS-in-JS、无原子类框架</td></tr><tr><td>测试</td><td>Vitest</td><td>只覆盖 3 个纯函数模块，跑在 node 环境，无组件测试</td></tr></tbody></table><p><strong>它与后端的关系</strong>：开发时是两个进程并行（Vite + Fastify）；生产时 Fastify 检测到 <code>apps/web/dist/index.html</code> 存在就直接静态托管该目录，并对非 <code>/api</code> 的 GET 回退首页。整个产品只监听回环地址，侧栏底部也直接写明了「仅监听 127.0.0.1」。</p><hr><h2 id="_3-启动链-四层嵌套容器" tabindex="-1">3. 启动链：四层嵌套容器 <a class="header-anchor" href="#_3-启动链-四层嵌套容器" aria-label="Permalink to &quot;3. 启动链：四层嵌套容器&quot;">​</a></h2><p><code>main.tsx</code> 从外到内依次包裹：</p>',10)),(e(),a(s,null,{default:d(()=>[c(o,{id:"mermaid-169",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20S%5B%22StrictMode%3Cbr%2F%3E%E5%BC%80%E5%8F%91%E6%9C%9F%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20Q%5B%22QueryClientProvider%3Cbr%2F%3E%E7%BB%9F%E4%B8%80%E7%BC%93%E5%AD%98%E4%B8%8E%E9%BB%98%E8%AE%A4%E7%AD%96%E7%95%A5%22%5D%0A%20%20%20%20Q%20--%3E%20V%5B%22ViewModeProvider%3Cbr%2F%3E%E7%AE%80%E5%8D%95%20%2F%20%E4%B8%93%E4%B8%9A%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20%20%20V%20--%3E%20R%5B%22BrowserRouter%3Cbr%2F%3EURL%20%E4%B8%8E%E9%A1%B5%E9%9D%A2%22%5D%0A%20%20%20%20R%20--%3E%20A%5B%22App%3Cbr%2F%3E%E8%B7%AF%E7%94%B1%E8%A1%A8%20%2B%20%E5%85%A8%E5%B1%80%E7%BB%84%E4%BB%B6%22%5D%0A"})]),fallback:d(()=>[...t[1]||(t[1]=[E(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=r('<p>随启动一起完成的还有两件事：一次性引入<strong>四份全局 CSS</strong>（主样式、引导、通知、邮件），以及<strong>仅在生产环境</strong>注册 Service Worker（注册失败只告警，不阻断应用）。</p><p>这个顺序有实际含义：视图模式在路由之外、缓存又在视图模式之外，所以任何页面都能读到同一份查询缓存和同一个模式开关，不必层层传 props。</p><hr><h2 id="_4-应用骨架-三个「隐形」组件-一层门禁" tabindex="-1">4. 应用骨架：三个「隐形」组件 + 一层门禁 <a class="header-anchor" href="#_4-应用骨架-三个「隐形」组件-一层门禁" aria-label="Permalink to &quot;4. 应用骨架：三个「隐形」组件 + 一层门禁&quot;">​</a></h2><p><code>App.tsx</code> 本身很薄——除了路由表，只挂了三个不渲染界面主体的组件：</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>关键设计</th></tr></thead><tbody><tr><td><code>EventBridge</code></td><td>订阅全局事件流，把事件名映射成需要失效的 queryKey</td><td>250ms 防抖后批量失效；无条件刷新一批基础 key（任务、健康、系统、审批、收件箱等），再按事件类型精准失效定时任务 / 会话 / 当前任务详情 / Git 等</td></tr><tr><td><code>NotificationCenter</code></td><td>把特定事件翻译成右上角 Toast</td><td>事件到通知的映射是纯函数；去重、最多 3 条、9 秒自动消失；页面隐藏且已授权时才升级为系统桌面通知</td></tr><tr><td><code>FirstRunGate</code></td><td>首次使用门禁</td><td>读 <code>/api/onboarding</code>，未完成配置时把根路径重定向到 <code>/welcome</code></td></tr></tbody></table><p><strong>路由结构</strong>分两层：</p><ul><li><code>/welcome</code>：独立的全屏 4 步引导页（接入模型 → 检查执行器 → 自动与主动 → 开始使用），不带侧栏。</li><li>其余页面全部包在 <code>AppShell</code> 内，由 <code>Outlet</code> 渲染：首页聊天、任务、任务详情、需要你、个人、运行、设备、定时任务、邮件、设置；未知路径一律回首页。</li><li><code>/memory</code> 与 <code>/methods</code> 两条旧路径被<strong>重定向</strong>到设置页的「记忆与技能」标签——这是功能收敛留下的痕迹。</li></ul><p><strong><code>AppShell</code> 是全局外壳</strong>：左侧固定侧栏（9 个导航项，任务数与「需要你」数带角标）、底部两张健康状态卡（聊天模型是否接入、执行器是否可用）、窄屏切换为 5 项底部导航，再加一个 <code>Ctrl/⌘ + K</code> 唤起的全屏命令面板。侧栏的角标数字由多个查询结果现场计算，不是后端下发的。</p>',9)),(e(),a(s,null,{default:d(()=>[c(o,{id:"mermaid-256",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20L1%5B%22%E5%90%AF%E5%8A%A8%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20P%5B%22Provider%20%E6%A0%88%20%C2%B7%20%E5%85%A8%E5%B1%80%E6%A0%B7%E5%BC%8F%20%C2%B7%20PWA%20%E6%B3%A8%E5%86%8C%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20L2%5B%22%E5%BA%94%E7%94%A8%E6%A0%B9%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22EventBridge%20%C2%B7%20%E9%80%9A%E7%9F%A5%E4%B8%AD%E5%BF%83%20%C2%B7%20%E9%A6%96%E5%90%AF%E9%97%A8%E7%A6%81%20%C2%B7%20%E8%B7%AF%E7%94%B1%E8%A1%A8%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20L3%5B%22%E7%95%8C%E9%9D%A2%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20U%5B%22AppShell%20%C2%B7%2011%20%E4%B8%AA%E9%A1%B5%E9%9D%A2%20%C2%B7%20%E7%AE%80%E5%8D%95%20%2F%20%E4%B8%93%E4%B8%9A%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20L4%5B%22%E6%95%B0%E6%8D%AE%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22api.ts%20%C2%B7%20types.ts%20%C2%B7%20%E5%8F%8C%20SSE%20%E9%80%9A%E9%81%93%20%C2%B7%20Query%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20L5%5B%22%E6%9C%8D%E5%8A%A1%E7%AB%AF%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22Fastify%20%2Fapi%20%C2%B7%20%E9%9D%99%E6%80%81%E6%89%98%E7%AE%A1%20dist%20%C2%B7%20SPA%20%E5%9B%9E%E9%80%80%22%5D%0A%20%20%20%20end%0A%20%20%20%20L1%20--%3E%20L2%20--%3E%20L3%20--%3E%20L4%20--%3E%20L5%0A"})]),fallback:d(()=>[...t[2]||(t[2]=[E(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=r('<hr><h2 id="_5-页面层-以聊天为入口-任务为核心" tabindex="-1">5. 页面层：以聊天为入口，任务为核心 <a class="header-anchor" href="#_5-页面层-以聊天为入口-任务为核心" aria-label="Permalink to &quot;5. 页面层：以聊天为入口，任务为核心&quot;">​</a></h2><p>约 11 个实际页面，按职责分三类：</p><table tabindex="0"><thead><tr><th>类别</th><th>页面</th><th>设计要点</th></tr></thead><tbody><tr><td>主链路</td><td>聊天（默认首页）、任务列表、任务详情、需要你</td><td>产品核心路径，状态变化最频繁</td></tr><tr><td>配置与运维</td><td>设置（9 个标签）、定时任务、设备、邮件、个人、运行、首启引导</td><td>表单与列表密集，取数以查询为主</td></tr><tr><td>可复用组件</td><td>外壳类、状态展示类、领域面板类</td><td>见下</td></tr></tbody></table><p><strong>组件目录的分工</strong>：</p><ul><li>外壳类：<code>AppShell</code>、<code>CommandPalette</code>、<code>NotificationCenter</code>、<code>HearthMark</code>、<code>EmptyState</code></li><li>状态展示类：<code>StatusPill</code> 一个文件导出十几种状态标签（任务 / 运行 / 效果 / 来源 / 发件箱 / 设备 / 桌面会话等），<code>TaskStatusIcon</code> 负责语义化图标</li><li>领域面板类：审批卡、任务补充面板、任务 Git 差异面板、工作区面板，以及执行器 / 飞书 / 主动设置三个设置子面板</li></ul><h3 id="_5-1-聊天页-交互最密集的地方" tabindex="-1">5.1 聊天页：交互最密集的地方 <a class="header-anchor" href="#_5-1-聊天页-交互最密集的地方" aria-label="Permalink to &quot;5.1 聊天页：交互最密集的地方&quot;">​</a></h3><p>三栏结构——左侧会话列表（每个会话还挂着自己派出的任务）、中间消息流、底部输入区。核心能力是<strong>一次请求自动分流成「直接回答」或「派出任务」</strong>，后端通过流式事件告知前端当前处于哪条路径。</p><table tabindex="0"><thead><tr><th>细节</th><th>做法</th></tr></thead><tbody><tr><td>流式事件</td><td>按事件名分流到不同本地状态：会话建立、用户消息、路由决策、记忆引用数、正文增量、思考过程、任务消息、任务提案、完成、错误</td></tr><tr><td>执行器控制</td><td>工具栏可<strong>锁定某个执行器</strong>，明确「不会自动切换」；不可用时直接阻止发送并给出诊断</td></tr><tr><td>权限控制</td><td>「必要审批 / 完全权限」一键切换，随会话保存</td></tr><tr><td>补充到任务</td><td>可把新消息补充进已有任务，并选择「轮后继续（queue）」或「中止本轮（steer）」；只有运行中任务才允许 steer</td></tr><tr><td>附件</td><td>先单独上传再随消息提交，最多 5 个、单个不超过 25 MB；补充到任务的模式不支持附件</td></tr><tr><td>输入体验</td><td>Enter 发送、Shift+Enter 换行，并专门处理中文输入法合成态；输入框高度自适应；发送中可用 AbortController 取消，卸载时自动中止</td></tr><tr><td>会话记忆</td><td>当前会话 ID 存 localStorage；收到 404 时自动重置为新对话并提示</td></tr></tbody></table><p>消息正文用 Markdown 渲染，支持复制、任务卡跳转等；空状态时给出 4 个引导性示例问题。</p><h3 id="_5-2-任务详情页-一次取回整个视图" tabindex="-1">5.2 任务详情页：一次取回整个视图 <a class="header-anchor" href="#_5-2-任务详情页-一次取回整个视图" aria-label="Permalink to &quot;5.2 任务详情页：一次取回整个视图&quot;">​</a></h3><p>与聊天页思路不同：它用<strong>单次查询拿回任务全貌</strong>（任务本体、运行记录、审批、事件、产物、上下文），以 4 秒轮询刷新，再用大量纯函数把原始事件翻译成人话、过滤技术噪音、拆分进度。审批、Git、工作区、补充队列等面板各自独立取数、各自发起变更，变更后只失效相关 key。</p><h3 id="_5-3-设置页-url-驱动的标签页" tabindex="-1">5.3 设置页：URL 驱动的标签页 <a class="header-anchor" href="#_5-3-设置页-url-驱动的标签页" aria-label="Permalink to &quot;5.3 设置页：URL 驱动的标签页&quot;">​</a></h3><p>9 个标签（执行器、模型、项目、扩展、主动、记忆与技能、连接、上下文、数据）用 <code>?tab=</code> 同步选中态，因此外部可以直接深链到某个设置分区——前面提到的两条旧路径正是重定向到这里。</p><hr><h2 id="_6-数据层-一个-api-门面-三条通道" tabindex="-1">6. 数据层：一个 API 门面 + 三条通道 <a class="header-anchor" href="#_6-数据层-一个-api-门面-三条通道" aria-label="Permalink to &quot;6. 数据层：一个 API 门面 + 三条通道&quot;">​</a></h2><p><code>lib/api.ts</code> 是<strong>唯一出口</strong>：一个大对象收纳上百个 REST 端点，全部经过统一的请求封装（自动补 JSON 头、按 content-type 解析响应、非 2xx 抛出带状态码与错误码的 <code>ApiError</code>）。附件上传用 FormData、导出下载用页面跳转，是少数特例。</p><p>类型定义在 <code>lib/types.ts</code>：<strong>大部分直接从后端共享包 <code>@hearth/core</code> 重导出</strong>，前端只补充「视图专用」类型，前后端共用一份类型契约。其余 lib 都是纯函数：中文标签字典、时间/字节/时长/相对时间格式化、事件到通知的映射、视图模式解析。</p><h3 id="_6-1-三条通道的分工-本套前端最核心的设计" tabindex="-1">6.1 三条通道的分工（本套前端最核心的设计） <a class="header-anchor" href="#_6-1-三条通道的分工-本套前端最核心的设计" aria-label="Permalink to &quot;6.1 三条通道的分工（本套前端最核心的设计）&quot;">​</a></h3>',19)),(e(),a(s,null,{default:d(()=>[c(o,{id:"mermaid-438",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20C1%5B%22%E9%80%9A%E9%81%93%E4%B8%80%20%C2%B7%20%E8%BD%AE%E8%AF%A2%E5%85%9C%E5%BA%95%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22%E5%AE%9A%E6%97%B6%E9%87%8D%E5%8F%96%3Cbr%2F%3E4s%20~%2030s%20%E4%B8%8D%E7%AD%89%22%5D%20--%3E%20A2%5B%22Query%20%E7%BC%93%E5%AD%98%3Cbr%2F%3E%E6%8C%89%20queryKey%20%E7%BB%84%E7%BB%87%22%5D%20--%3E%20A3%5B%22%E9%A1%B5%E9%9D%A2%E8%87%AA%E5%8A%A8%E5%88%B7%E6%96%B0%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20C2%5B%22%E9%80%9A%E9%81%93%E4%BA%8C%20%C2%B7%20%E5%85%A8%E5%B1%80%20SSE%22%5D%0A%20%20%20%20%20%20%20%20B1%5B%22%2Fapi%2Fevents%3Cbr%2F%3E%E7%BA%A6%2060%20%E7%A7%8D%E5%85%B7%E5%90%8D%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20B2%5B%22EventBridge%3Cbr%2F%3E250ms%20%E9%98%B2%E6%8A%96%20%2B%20%E4%BA%8B%E4%BB%B6%E6%98%A0%E5%B0%84%22%5D%20--%3E%20B3%5B%22%E6%8C%89%20key%20%E7%B2%BE%E5%87%86%E5%A4%B1%E6%95%88%3Cbr%2F%3E%E5%8F%AA%E9%87%8D%E5%8F%96%E7%9B%B8%E5%85%B3%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20C3%5B%22%E9%80%9A%E9%81%93%E4%B8%89%20%C2%B7%20%E8%81%8A%E5%A4%A9%E6%B5%81%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22POST%20%2Fapi%2Fchat%3Cbr%2F%3E%E6%89%8B%E5%B7%A5%E8%A7%A3%E6%9E%90%20SSE%20%E5%88%86%E5%9D%97%22%5D%20--%3E%20D2%5B%22%E9%A1%B5%E9%9D%A2%E6%9C%AC%E5%9C%B0%20state%3Cbr%2F%3E%E9%80%90%E5%AD%97%E8%BF%BD%E5%8A%A0%20%C2%B7%20%E8%B7%AF%E7%94%B1%E6%80%81%20%C2%B7%20%E6%8F%90%E6%A1%88%22%5D%20--%3E%20D3%5B%22%E7%BB%93%E6%9D%9F%E5%90%8E%E5%A4%B1%E6%95%88%3Cbr%2F%3E%E5%9B%9E%E5%86%99%E4%BC%9A%E8%AF%9D%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20end%0A"})]),fallback:d(()=>[...t[3]||(t[3]=[E(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=r('<table tabindex="0"><thead><tr><th>通道</th><th>传的是什么</th><th>为什么不直接用它渲染</th></tr></thead><tbody><tr><td>定时轮询</td><td>完整业务数据</td><td>兜底：即使事件丢失也能收敛到正确状态</td></tr><tr><td>全局 SSE</td><td><strong>只有事件名 + 信封</strong>，不含业务数据</td><td>事件只报「脏」，数据仍由 REST 拉取，避免前端维护两套状态副本</td></tr><tr><td>聊天流 SSE</td><td>逐字正文、思考、路由、任务、提案、错误</td><td>强实时、一次性、与缓存无关，<strong>刻意不进 Query 缓存</strong>，只在流结束后失效会话相关 key</td></tr></tbody></table><p>聊天流用的是 <code>fetch</code> + 可读流手工分块解析（按空行切块、解析事件名与数据行、JSON 解析失败则退回原始文本），而不是 <code>EventSource</code>——因为它是 POST 且需要中途取消。</p><h3 id="_6-2-状态管理规则" tabindex="-1">6.2 状态管理规则 <a class="header-anchor" href="#_6-2-状态管理规则" aria-label="Permalink to &quot;6.2 状态管理规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态种类</th><th>放在哪</th><th>例子</th></tr></thead><tbody><tr><td>服务端状态</td><td>Query 缓存，以 queryKey 为约定</td><td>任务、会话、审批、健康、设置</td></tr><tr><td>瞬时交互状态</td><td>组件本地 state</td><td>输入内容、流式正文、弹窗开关、当前预览</td></tr><tr><td>跨页 UI 偏好</td><td>Context 或 localStorage</td><td>当前会话 ID、桌面通知开关、简单/专业模式</td></tr><tr><td>变更副作用</td><td>mutation 成功后 <code>invalidateQueries</code></td><td>审批通过、任务取消、设置保存</td></tr></tbody></table><p><strong>要点</strong>：跨组件一致性不靠「共享 store」，靠大家遵守同一套 queryKey 命名，并在变更后显式失效。这也是这套设计最主要的隐性约束。</p><hr><h2 id="_7-视觉与样式体系" tabindex="-1">7. 视觉与样式体系 <a class="header-anchor" href="#_7-视觉与样式体系" aria-label="Permalink to &quot;7. 视觉与样式体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>做法</th></tr></thead><tbody><tr><td>文件组织</td><td><code>styles.css</code> 是约 9000 行的单文件，按编号注释分节；另有 <code>wizard.css</code>、<code>notifications.css</code>、<code>mail.css</code> 三份按领域拆出的补充样式</td></tr><tr><td>分节顺序</td><td>设计 token → 重置与排版 → 外壳 → 按钮/标签/状态 → 面板/表格/列表 → 功能块 → 响应式 → 各功能域补丁</td></tr><tr><td>设计 token</td><td>集中在 <code>:root</code>：炭黑、余烬橙、沙色、米白构成一套<strong>浅色暖调</strong>主题；字号 11–20px、间距、圆角、焦点环全部变量化；注释明确「橙色不承载小字」</td></tr><tr><td>排版</td><td>页面整体不滚动（<code>body</code> 溢出隐藏），由各面板内部独立滚动；数字使用等宽数字；统一中文字体栈</td></tr><tr><td>响应式</td><td>30 多处媒体查询，1040 / 900 / 820 / 760 / 720 / 640 等断点层层收窄；单独处理矮屏、移动端安全区、「减少动效」偏好与无 hover 设备</td></tr><tr><td>国际化</td><td>全站中文文案硬编码在组件与标签字典里，<strong>没有 i18n 框架</strong></td></tr></tbody></table><hr><h2 id="_8-pwa-与离线策略" tabindex="-1">8. PWA 与离线策略 <a class="header-anchor" href="#_8-pwa-与离线策略" aria-label="Permalink to &quot;8. PWA 与离线策略&quot;">​</a></h2><p>manifest 配好名称、图标、<code>standalone</code> 模式与主题色；Service Worker 的策略非常克制：</p><ul><li><strong>只缓存应用外壳</strong>（首页、manifest、三张图标），缓存名带版本号，激活时清掉旧版本</li><li><strong>明确跳过所有 <code>/api/</code> 请求与非 GET 请求</strong>——绝不缓存业务数据</li><li>导航请求：网络优先，失败时回落到缓存的首页（保证离线能打开界面）</li><li>静态资源：缓存优先，未命中则请求并把成功响应回填进缓存</li></ul><p>也就是说，离线时能看到界面外壳，但不会看到过期的任务或审批数据。</p><hr><h2 id="_9-交互细节速查" tabindex="-1">9. 交互细节速查 <a class="header-anchor" href="#_9-交互细节速查" aria-label="Permalink to &quot;9. 交互细节速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td><code>Ctrl/⌘ + K</code></td><td>打开命令面板，可搜页面与任务</td></tr><tr><td><code>Alt + M</code></td><td>在「简单 / 专业」模式间切换（隐藏快捷键，界面上无开关）</td></tr><tr><td><code>?mode=pro</code> / <code>?mode=simple</code></td><td>临时覆盖视图模式，且<strong>不写回 localStorage</strong></td></tr><tr><td><code>/settings?tab=xxx</code></td><td>直接深链到某个设置分区</td></tr><tr><td><code>Enter</code> / <code>Shift + Enter</code></td><td>发送 / 换行（含中文输入法保护）</td></tr><tr><td><code>Esc</code></td><td>关闭命令面板</td></tr><tr><td>命令面板内 <code>Enter</code></td><td>打开第一项结果</td></tr></tbody></table><p><strong>双视图模式</strong>由 Context 实现：默认简单版，localStorage 记忆偏好，URL 参数优先级最高；读取/写入 localStorage 都做了异常兜底（隐私模式下降级为简单版），快捷键还会避开输入框与可编辑区域。但全项目<strong>只有审批卡与设备页两处真正消费它</strong>，用来显隐审计明细、原始命令等高级信息。</p><hr><h2 id="_10-只有读代码才会发现的事实" tabindex="-1">10. 只有读代码才会发现的事实 <a class="header-anchor" href="#_10-只有读代码才会发现的事实" aria-label="Permalink to &quot;10. 只有读代码才会发现的事实&quot;">​</a></h2><ol><li><strong>有 5 个孤立页面</strong>：<code>OperationsPage</code>、<code>SecurityPage</code>、<code>SyncPage</code>、<code>MemoryPage</code>、<code>MethodsPage</code> 都完整存在，但没有任何路由或 import 引用它们，功能应已并入设置页。</li><li><strong>双视图的覆盖面很小</strong>：机制做得很完整（Context、持久化、URL 覆盖、快捷键、纯函数测试），却只有 2 处消费，且没有可见开关。</li><li><strong>测试只覆盖纯函数</strong>：3 个测试文件分别是标签字典、通知映射、视图模式解析；没有组件渲染或交互测试。</li><li><strong>明显的「纵向堆叠」风格</strong>：<code>api.ts</code> 近 800 行、<code>SettingsPage.tsx</code> 约 1300 行、<code>ChatPage.tsx</code> 约 1000 行、<code>styles.css</code> 约 9000 行，都是按功能域持续追加，而非严格分层拆分。</li><li><strong>轮询 + SSE 双保险</strong>：几乎所有实时页面同时挂了定时轮询和事件失效，实时性好，代价是请求量偏大。</li><li><strong>类型是跨包共享的</strong>：前端类型大量重导出自 <code>@hearth/core</code>，后端改数据结构会直接反映到前端编译结果上。</li></ol><hr><h2 id="_11-设计取舍小结" tabindex="-1">11. 设计取舍小结 <a class="header-anchor" href="#_11-设计取舍小结" aria-label="Permalink to &quot;11. 设计取舍小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>得到的好处</th><th>付出的代价</th></tr></thead><tbody><tr><td>无状态库，服务端状态只有一份真相</td><td>queryKey 命名靠约定，变更后忘记失效就会出现「界面不更新」</td></tr><tr><td>事件只报脏、数据统一由 REST 拉取，避免两套状态副本</td><td>一次事件往往触发多批次重取，需要 250ms 防抖来削峰</td></tr><tr><td>聊天流独立处理，逐字体验好、可随时取消</td><td>这部分状态游离于缓存之外，页面卸载需手动中止、结束后需手动回写</td></tr><tr><td>前后端共享类型契约，重构有编译期保障</td><td>前端与后端包耦合较紧</td></tr><tr><td>手写 CSS + 双视图，能精确控制信息密度</td><td>单文件持续膨胀；高级功能藏得较深，可发现性弱</td></tr><tr><td>PWA 外壳离线可用、业务数据绝不缓存</td><td>离线仅能打开界面，不能查看任何实际内容</td></tr></tbody></table><p><strong>一句话总结</strong>：这是一个「事件驱动 + 缓存即状态」的本地控制台前端——用 REST 与查询缓存承载所有持久状态，用全局 SSE 只做失效通知，用独立流式通道处理实时对话；界面围绕「聊天派活、任务审计、需要你确认」三件事组织，并用双视图模式把高级细节藏起来。</p><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>启动与全局配置</td><td><code>apps/web/src/main.tsx</code>、<code>vite.config.ts</code>、<code>tsconfig.json</code></td></tr><tr><td>路由与全局组件</td><td><code>apps/web/src/App.tsx</code></td></tr><tr><td>外壳、导航、命令面板</td><td><code>apps/web/src/components/AppShell.tsx</code>、<code>CommandPalette.tsx</code></td></tr><tr><td>通知与事件桥</td><td><code>App.tsx</code> 的 <code>EventBridge</code>、<code>components/NotificationCenter.tsx</code></td></tr><tr><td>聊天主链路</td><td><code>pages/ChatPage.tsx</code></td></tr><tr><td>任务主链路</td><td><code>pages/TasksPage.tsx</code>、<code>TaskDetailPage.tsx</code></td></tr><tr><td>API 与流式解析</td><td><code>lib/api.ts</code>（文件尾部是两个 SSE 相关函数）</td></tr><tr><td>类型、文案、格式化</td><td><code>lib/types.ts</code>、<code>labels.ts</code>、<code>format.ts</code></td></tr><tr><td>视图模式</td><td><code>lib/view-mode.tsx</code></td></tr><tr><td>样式</td><td><code>styles.css</code>（按编号注释分节）、<code>wizard.css</code>、<code>notifications.css</code>、<code>mail.css</code></td></tr><tr><td>PWA</td><td><code>public/manifest.webmanifest</code>、<code>public/sw.js</code>、<code>index.html</code></td></tr><tr><td>静态托管</td><td><code>apps/server/src/app.ts</code> 中注册静态资源与 404 回退的部分</td></tr></tbody></table>',27))])}const m=i(h,[["render",A]]);export{_ as __pageData,m as default};
